local RegressionNewRewardAniRootCell = Class('RegressionNewRewardAniRootCell')

function RegressionNewRewardAniRootCell:__init()

end

function RegressionNewRewardAniRootCell:__delete()

end

function RegressionNewRewardAniRootCell:Awake()
	self:RefreshRewardState(true)
end

function RegressionNewRewardAniRootCell:RefreshGridShow(data, index)
	self.data = data
	self.index = index
	local isStart = self.data.isOrigin == 1
	
	if isStart then
		CfUtils.SetActive(self.ImgBgRandom.gameObject,false)
		CfUtils.SetActive(self.ImgBg.gameObject,true)
		CfUtils.SetUISwitchImage(self.ImgBg, 1)
	else
		local isRandom = checkNumber(self.data.isRandom)  == 1
		CfUtils.SetActive(self.ImgBgRandom.gameObject,isRandom)
		CfUtils.SetActive(self.ImgBg.gameObject,not isRandom)
		self:RefreshRewardState(not isRandom)
		if not isRandom then
			CfUtils.SetUISwitchImage(self.ImgBg, 2)
		end
	end
	self:RefreshRewardShow()
end

function RegressionNewRewardAniRootCell:RefreshRewardState(state)
	CfUtils.SetActive(self.ImgRewardIcon.gameObject,state)
end

function RegressionNewRewardAniRootCell:SetRewardState(state)
	local isRandom = checkNumber(self.data.isRandom)  == 1
	if not isRandom then
		self:RefreshRewardState(state)
	else
		self:RefreshRewardState(false)
		CfUtils.SetActive(self.ImgRandom.gameObject, state)
	end
end

function RegressionNewRewardAniRootCell:PlayJumpEffect()
	CfUtils.PlayAnimation(self.Root,"RegressionNewRewardDialog_CellJumpEffect")
end

function RegressionNewRewardAniRootCell:PlayEffect(isEntry)
	local aniName = isEntry and "RegressionNewRewardDialog_CellIconEntry" or "RegressionNewRewardDialog_CellIconOut"
	CfUtils.PlayAnimation(self.controller,aniName)
end

function RegressionNewRewardAniRootCell:RefreshRewardShow()
	local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.reward)
	if isNotNull(goodsVo) then
		CfUtils.FillImage(self.ImgRewardIcon, goodsVo.photoPath)
	end
	CfUtils.FillText(self.TxtNum, self.data.rewardNum)
end

function RegressionNewRewardAniRootCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return RegressionNewRewardAniRootCell